var data = typeof payload === 'string' ? JSON.parse(payload) : JSON.parse(String.fromCharCode.apply(null, payload));
var deviceName = metadata.topic.split('/')[0];
var result = {
    deviceName: deviceName,
    deviceType: 'Shelly Pro EM50',
    telemetry: {}
};

var topic = metadata.topic;

if (topic.indexOf('/status/em1:0') !== -1) {
    result.telemetry = {
        voltaje_canal_0:          data.voltage,
        corriente_canal_0:        data.current,
        potencia_activa_canal_0:  data.act_power,
        potencia_aparente_canal_0: data.aprt_power,
        factor_potencia_canal_0:  data.pf,
        frecuencia_canal_0:       data.freq
    };
} else if (topic.indexOf('/status/em1:1') !== -1) {
    result.telemetry = {
        voltaje_canal_1:          data.voltage,
        corriente_canal_1:        data.current,
        potencia_activa_canal_1:  data.act_power,
        potencia_aparente_canal_1: data.aprt_power,
        factor_potencia_canal_1:  data.pf,
        frecuencia_canal_1:       data.freq
    };
} else if (topic.indexOf('/status/em1data:0') !== -1) {
    result.telemetry = {
        energia_canal_0:     data.total_act_energy,
        energia_ret_canal_0: data.total_act_ret_energy
    };
} else if (topic.indexOf('/status/em1data:1') !== -1) {
    result.telemetry = {
        energia_canal_1:     data.total_act_energy,
        energia_ret_canal_1: data.total_act_ret_energy
    };
}

return result;

